import pathlib,re
for f in sorted(pathlib.Path('/docs').glob('*.txt')):
 p='?'; hits=[]
 for l in f.read_text().replace('\\xa0',' ').splitlines():
  m=re.search(r'--- page (\\d+) ---',l)
